const STATUS_KEY="ooh_shelter_status_v3";
const statusMap=JSON.parse(localStorage.getItem(STATUS_KEY)||"{}");
let activeArea="All",searchTerm="",radiusKm=null,currentPos=null,userMarker=null,selectedId=null,remainingOnly=false,labelMode=localStorage.getItem("ooh_site_labels")||"auto";
let driving=false,followDriving=true,headingUp=true,watchId=null,lastHeading=0,lastSpeed=0,currentDriveSite=null,last500Site=null,lastAlertSite=null,lastArrivalSite=null,routeLine=null,smoothedBearing=0,drivingFocusKm=2;
let lastGpsSample=null,arrivalConfirmCount=0,currentAccuracy=999;
const DEFAULT_DRIVE_SETTINGS={voice:true,vibrate:true,wake:true,autoHide:5000,orientation:'heading',arrivalMetres:50};
let driveSettings={...DEFAULT_DRIVE_SETTINGS,...JSON.parse(localStorage.getItem('shelter_pro_drive_settings')||'{}')};
function speak(text){if(!driveSettings.voice)return;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.rate=.95;speechSynthesis.speak(u);}catch(e){}}
function buzz(pattern){if(driveSettings.vibrate&&navigator.vibrate)navigator.vibrate(pattern);}
const map=L.map("map",{preferCanvas:true,rotate:true,bearing:0,touchRotate:false}).setView([-33.82,151.02],10);
L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:"&copy; OpenStreetMap contributors"}).addTo(map);
const markerLayer=L.markerClusterGroup({chunkedLoading:true,showCoverageOnHover:false,spiderfyOnMaxZoom:true,maxClusterRadius:55,disableClusteringAtZoom:15}).addTo(map);
const markerById=new Map();
function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function statusOf(id){return statusMap[id]||"none"}
function saveStatus(id,status){if(status==="none")delete statusMap[id];else statusMap[id]=status;localStorage.setItem(STATUS_KEY,JSON.stringify(statusMap));render();}
function hav(lat1,lon1,lat2,lon2){const R=6371,dLat=(lat2-lat1)*Math.PI/180,dLon=(lon2-lon1)*Math.PI/180;const a=Math.sin(dLat/2)**2+Math.cos(lat1*Math.PI/180)*Math.cos(lat2*Math.PI/180)*Math.sin(dLon/2)**2;return 2*R*Math.asin(Math.sqrt(a));}
function appleMaps(s){
  if(!s){alert("Shelter location is unavailable.");return;}
  const destination=(s.address&&s.address.trim())?s.address:`${s.lat},${s.lon}`;
  const url=`https://maps.apple.com/directions?destination=${encodeURIComponent(destination)}&mode=driving`;
  window.location.assign(url);
}
function googleMaps(s){window.location.href=`https://www.google.com/maps/dir/?api=1&destination=${s.lat},${s.lon}&travelmode=driving`}
function wazeMaps(s){window.location.href=`https://waze.com/ul?ll=${s.lat}%2C${s.lon}&navigate=yes&utm_source=shelterpro`}
async function copyText(text,label){try{await navigator.clipboard.writeText(text);alert(label+" copied");}catch(e){prompt("Copy this:",text);}}
function filteredSites(){const t=searchTerm.trim().toLowerCase();return SITES.filter(s=>{const todayIds=activeArea==="Today"?(window.ShelterProWorkflow?.getJobs?.()||[]):null;const routeIds=activeArea==="Route"?(window.ShelterProState?.getRoute?.()||[]):null;const areaOK=activeArea==="All"||(activeArea==="Today"?todayIds.includes(String(s.id)):activeArea==="Route"?routeIds.includes(String(s.id)):s.area===activeArea);const hay=`${s.id} ${s.address} ${s.owner} ${s.customer} ${s.asset}`.toLowerCase();const searchOK=!t||hay.includes(t);const nearOK=!radiusKm||(currentPos&&hav(currentPos.lat,currentPos.lon,s.lat,s.lon)<=radiusKm);const remOK=!remainingOnly||statusOf(s.id)==="none";return areaOK&&searchOK&&nearOK&&remOK;}).sort((a,b)=>currentPos?hav(currentPos.lat,currentPos.lon,a.lat,a.lon)-hav(currentPos.lat,currentPos.lon,b.lat,b.lon):String(a.id).localeCompare(String(b.id),undefined,{numeric:true}));}
function selectSite(id,zoom=true){selectedId=id;const s=SITES.find(x=>x.id===id);if(!s)return;if(zoom)map.setView([s.lat,s.lon],17,{animate:true});const marker=markerById.get(id);if(marker)markerLayer.zoomToShowLayer(marker,()=>marker.openPopup());renderListOnly();setTimeout(()=>document.getElementById('site-'+CSS.escape(id))?.scrollIntoView({behavior:'smooth',block:'nearest'}),100);}
function card(s){const st=statusOf(s.id),distance=currentPos?` • ${hav(currentPos.lat,currentPos.lon,s.lat,s.lon).toFixed(1)} km`:"",statusLabel=st==="none"?"Remaining":st[0].toUpperCase()+st.slice(1);return `<article id="site-${esc(s.id)}" class="site-card ${selectedId===s.id?'selected':''}" onclick="selectSite('${String(s.id).replace(/'/g,"\'")}',true)"><div class="site-title"><span class="site-id">Site ${esc(s.id)}</span><span class="badges"><span class="area-badge">${esc(s.area)}</span><span class="status-badge">${esc(statusLabel)}</span></span></div><div class="address">${esc(s.address||'No address')}</div><div class="meta">${esc(s.owner)}${distance}${s.blocking?` • ${esc(s.blocking)}`:''}</div><div class="actions"><button class="primary" onclick="event.stopPropagation();appleMaps(SITES.find(x=>x.id==='${String(s.id).replace(/'/g,"\'")}'))">Apple Maps (GPS)</button><button onclick="event.stopPropagation();googleMaps(SITES.find(x=>x.id==='${String(s.id).replace(/'/g,"\'")}'))">Google Maps (GPS)</button></div><div class="secondary-actions"><button onclick="event.stopPropagation();wazeMaps(SITES.find(x=>x.id==='${String(s.id).replace(/'/g,"\'")}'))">Waze</button><button onclick="event.stopPropagation();copyText('${s.lat}, ${s.lon}','Coordinates')">Copy GPS</button><button onclick="event.stopPropagation();addToRoute(site.id,site.address)">➕ Route</button><button onclick="event.stopPropagation();copyText(${JSON.stringify(s.address)},'Address')">Copy address</button><button onclick="event.stopPropagation();selectSite('${String(s.id).replace(/'/g,"\'")}',true)">Show map</button></div><div class="status-row"><button class="status-cleaned" onclick="event.stopPropagation();saveStatus('${String(s.id).replace(/'/g,"\'")}','cleaned')">Cleaned</button><button class="status-skipped" onclick="event.stopPropagation();saveStatus('${String(s.id).replace(/'/g,"\'")}','skipped')">Skipped</button><button class="status-blocked" onclick="event.stopPropagation();saveStatus('${String(s.id).replace(/'/g,"\'")}','blocked')">Blocked</button><button class="status-qa" onclick="event.stopPropagation();saveStatus('${String(s.id).replace(/'/g,"\'")}','qa')">QA</button></div></article>`;}
function updateDashboard(items){const counts={cleaned:0,skipped:0,blocked:0,qa:0};items.forEach(s=>{const st=statusOf(s.id);if(counts[st]!==undefined)counts[st]++;});document.getElementById('dTotal').textContent=items.length.toLocaleString();document.getElementById('dCleaned').textContent=counts.cleaned;document.getElementById('dSkipped').textContent=counts.skipped;document.getElementById('dBlocked').textContent=counts.blocked;document.getElementById('dQA').textContent=counts.qa;}
function renderListOnly(){const items=filteredSites();document.getElementById('count').textContent=`${items.length.toLocaleString()} sites${radiusKm?` within ${radiusKm} km`:''}`;document.getElementById('list').innerHTML=items.slice(0,150).map(card).join('')||'<div class="empty">No matching sites.</div>';updateDashboard(items);}
function markerColor(st){return st==='cleaned'?'#16853c':st==='skipped'?'#b26a00':st==='blocked'?'#c5221f':st==='qa'?'#0b57d0':'#5f6b7a'}
function render(){const items=filteredSites();renderListOnly();markerLayer.clearLayers();markerById.clear();items.forEach(s=>{const marker=L.circleMarker([s.lat,s.lon],{radius:selectedId===s.id?9:6,weight:selectedId===s.id?4:2,color:markerColor(statusOf(s.id)),fillOpacity:.8}).bindTooltip(`Site ${esc(s.id)}`,{permanent:true,direction:'top',offset:[0,-7],className:'site-number-label',interactive:false,opacity:1}).bindPopup(`<b>Site ${esc(s.id)}</b><br>${esc(s.address)}<br><small>${esc(s.owner)} • ${esc(s.area)}</small><br><button onclick="appleMaps(SITES.find(x=>String(x.id)===String('${String(s.id).replace(/'/g,"\'")}')))">Apple Maps</button>`);marker.on('click',()=>{selectedId=s.id;renderListOnly();});markerById.set(s.id,marker);markerLayer.addLayer(marker);});}
document.getElementById('search').addEventListener('input',e=>{searchTerm=e.target.value;selectedId=null;render();const items=filteredSites();if(searchTerm.trim()&&items.length===1)selectSite(items[0].id,true);});
document.querySelectorAll('[data-area]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-area]').forEach(b=>b.classList.remove('active'));btn.classList.add('active');activeArea=btn.dataset.area;selectedId=null;render();}));
function useRadius(km){radiusKm=km;if(!currentPos)map.locate({setView:true,maxZoom:14});else render();}
document.getElementById('near5').onclick=()=>useRadius(5);document.getElementById('near10').onclick=()=>useRadius(10);document.getElementById('near20').onclick=()=>useRadius(20);document.getElementById('clearNear').onclick=()=>{radiusKm=null;render();};
document.getElementById('nearest').onclick=()=>{if(!currentPos){map.locate({setView:true,maxZoom:16});return;}const item=filteredSites()[0];if(item)selectSite(item.id,true);};
document.getElementById('locate').onclick=()=>map.locate({setView:true,maxZoom:16});
map.on('locationfound',e=>handlePosition({coords:{latitude:e.latitude,longitude:e.longitude,accuracy:e.accuracy,speed:null,heading:null}}));map.on('locationerror',()=>alert('Location unavailable. Check browser location permission.'));
document.getElementById('showRemaining').onclick=()=>{remainingOnly=!remainingOnly;document.getElementById('showRemaining').textContent=remainingOnly?'Show all':'Remaining only';render();};
document.getElementById('reset').onclick=()=>{if(confirm('Clear all saved statuses?')){localStorage.removeItem(STATUS_KEY);Object.keys(statusMap).forEach(k=>delete statusMap[k]);render();}};

function compassName(deg){if(!Number.isFinite(deg))return '—';return ['N','NE','E','SE','S','SW','W','NW'][Math.round(deg/45)%8];}
function destination(lat,lon,bearing,km){const R=6371,d=km/R,b=bearing*Math.PI/180,p1=lat*Math.PI/180,l1=lon*Math.PI/180;const p2=Math.asin(Math.sin(p1)*Math.cos(d)+Math.cos(p1)*Math.sin(d)*Math.cos(b));const l2=l1+Math.atan2(Math.sin(b)*Math.sin(d)*Math.cos(p1),Math.cos(d)-Math.sin(p1)*Math.sin(p2));return [p2*180/Math.PI,l2*180/Math.PI];}
function remainingDriveSites(){const ids=window.ShelterProWorkflow?.getQueue?.()||[];if(ids.length)return ids.map(id=>SITES.find(s=>String(s.id)===String(id))).filter(Boolean).filter(s=>statusOf(s.id)==='none');return SITES.filter(s=>statusOf(s.id)==='none');}
function nearestDriveSite(){const candidates=remainingDriveSites();if(!candidates.length)return null;const managed=(window.ShelterProWorkflow?.getQueue?.()||[]).length>0;if(managed)return candidates[0];if(!currentPos)return candidates[0];return candidates.sort((a,b)=>hav(currentPos.lat,currentPos.lon,a.lat,a.lon)-hav(currentPos.lat,currentPos.lon,b.lat,b.lon))[0]||null;}
function angleDelta(from,to){return ((to-from+540)%360)-180;}
function setBearing(deg){if(!headingUp||!Number.isFinite(deg)||lastSpeed<8)return;if(!Number.isFinite(smoothedBearing))smoothedBearing=deg;smoothedBearing=(smoothedBearing+angleDelta(smoothedBearing,deg)*.28+360)%360;if(typeof map.setBearing==='function')map.setBearing(smoothedBearing);}
function drawRouteLine(){if(routeLine){try{map.removeLayer(routeLine);}catch(_){ }routeLine=null;}/* Direct GPS-to-shelter line permanently disabled. */}
function updateDrivingMarkers(){if(!driving||!currentPos)return;const nearby=SITES.filter(s=>hav(currentPos.lat,currentPos.lon,s.lat,s.lon)<=drivingFocusKm||s.id===selectedId);markerLayer.clearLayers();markerById.clear();nearby.forEach(s=>{const active=s.id===selectedId;const marker=L.circleMarker([s.lat,s.lon],{radius:active?13:7,weight:active?5:2,color:active?'#ff7a00':markerColor(statusOf(s.id)),fillColor:active?'#ff7a00':markerColor(statusOf(s.id)),fillOpacity:.9,className:active?'destination-pulse':''}).bindTooltip(`Site ${esc(s.id)}`,{permanent:true,direction:'top',offset:[0,-8],className:'site-number-label',interactive:false,opacity:1}).bindPopup(`<b>Site ${esc(s.id)}</b><br>${esc(s.address)}`);marker.on('click',()=>{selectedId=s.id;currentDriveSite=s;updateDrivingView();});markerById.set(s.id,marker);markerLayer.addLayer(marker);});}
function updateDrivingView(){if(!driving||!currentPos)return;
 const dashboard=document.getElementById('driveDashboard');dashboard.classList.remove('approaching','arrived');
 currentDriveSite=nearestDriveSite();const remaining=remainingDriveSites();const completed=SITES.length-remaining.length;
 document.getElementById('driveRemaining').textContent=remaining.length.toLocaleString();
 document.getElementById('driveProgressText').textContent=completed.toLocaleString()+' / '+SITES.length.toLocaleString();
 document.getElementById('driveProgressFill').style.width=Math.min(100,(completed/SITES.length)*100)+'%';
 const statusEl=document.getElementById('driveStatus');statusEl.className='drive-status';statusEl.textContent='Navigating';
 if(currentDriveSite){selectedId=currentDriveSite.id;const km=hav(currentPos.lat,currentPos.lon,currentDriveSite.lat,currentDriveSite.lon);const metres=Math.round(km*1000);
  document.getElementById('driveSite').textContent='Site '+currentDriveSite.id;document.getElementById('driveAddress').textContent=currentDriveSite.address;document.getElementById('driveDistance').textContent=km<1?metres+' m':km.toFixed(1)+' km';
  const etaMinutes=Math.max(1,Math.round(km/Math.max(lastSpeed,10)*60));document.getElementById('driveETA').textContent=etaMinutes+' min';
  if(km<=.5&&last500Site!==currentDriveSite.id){last500Site=currentDriveSite.id;showDrivingDashboard(5500);speak('Approaching site '+currentDriveSite.id+' in five hundred metres')}
  if(km<=.2){showDrivingDashboard(5000);dashboard.classList.add('approaching');statusEl.classList.add('approach');statusEl.textContent='Approaching · '+metres+' m';}
  if(km<=.2&&lastAlertSite!==currentDriveSite.id){lastAlertSite=currentDriveSite.id;buzz([250,120,250]);speak('Approaching site '+currentDriveSite.id)}
  const arrivalKm=driveSettings.arrivalMetres/1000;
  if(km<=arrivalKm&&currentAccuracy<=Math.max(65,driveSettings.arrivalMetres+20))arrivalConfirmCount++;else arrivalConfirmCount=0;
  if(arrivalConfirmCount>=2){showDrivingDashboard(7000);dashboard.classList.remove('approaching');dashboard.classList.add('arrived');statusEl.classList.remove('approach');statusEl.classList.add('arrival');statusEl.textContent='Arrived';}
  if(arrivalConfirmCount>=2&&lastArrivalSite!==currentDriveSite.id){lastArrivalSite=currentDriveSite.id;buzz([400,120,400,120,400]);speak('You have arrived at site '+currentDriveSite.id)}
  drawRouteLine(currentDriveSite);updateDrivingMarkers();
 }else{document.getElementById('driveSite').textContent='All shelters completed';document.getElementById('driveAddress').textContent='No remaining sites';document.getElementById('driveDistance').textContent='—';document.getElementById('driveETA').textContent='—';statusEl.textContent='Finished';drawRouteLine(null);}
 document.getElementById('driveSpeed').textContent=Math.round(lastSpeed||0);document.getElementById('driveHeading').textContent=compassName(lastHeading)+' '+Math.round(lastHeading||0)+'°';const miniSite=document.getElementById('miniSite'),miniDetails=document.getElementById('miniDetails');document.getElementById('miniSpeed').textContent=Math.round(lastSpeed||0);if(currentDriveSite){miniSite.textContent='Site '+currentDriveSite.id+' · '+document.getElementById('driveDistance').textContent;miniDetails.textContent='ETA '+document.getElementById('driveETA').textContent+' · '+document.getElementById('driveRemaining').textContent+' remaining · tap for controls';}else{miniSite.textContent='All shelters completed';miniDetails.textContent='Tap for driving controls';}
 if(followDriving){const zoom=lastSpeed>70?15:lastSpeed>35?16:17;const leadKm=lastSpeed>60?.22:lastSpeed>25?.15:.09;const centre=destination(currentPos.lat,currentPos.lon,lastHeading||0,leadKm);map.setView(centre,zoom,{animate:true,duration:.45});setBearing(lastHeading||0);}
}
function handlePosition(pos){const c=pos.coords;const now=Date.now();currentAccuracy=Number.isFinite(c.accuracy)?c.accuracy:999;document.getElementById('app').classList.toggle('gps-poor',currentAccuracy>60);const nextPos={lat:c.latitude,lon:c.longitude};let rawSpeed=Number.isFinite(c.speed)&&c.speed>=0?c.speed*3.6:null;if(rawSpeed===null&&lastGpsSample){const seconds=(now-lastGpsSample.time)/1000;if(seconds>.4&&seconds<10)rawSpeed=hav(lastGpsSample.lat,lastGpsSample.lon,nextPos.lat,nextPos.lon)*3600/seconds;}if(rawSpeed!==null&&rawSpeed<180)lastSpeed=lastSpeed?lastSpeed*.68+rawSpeed*.32:rawSpeed;if(lastSpeed<1.5)lastSpeed=0;if(Number.isFinite(c.heading)&&c.heading>=0&&lastSpeed>3)lastHeading=c.heading;currentPos=nextPos;lastGpsSample={...nextPos,time:now};if(userMarker)map.removeLayer(userMarker);const uteSvg=`<div class="user-driving-marker"><svg viewBox="0 0 34 54" aria-label="oOh maintenance ute"><rect x="5" y="3" width="24" height="48" rx="5" fill="#fff" stroke="#1f2937" stroke-width="1.4"/><path d="M7 5h20v21H7z" fill="#fff"/><line x1="6" y1="26" x2="28" y2="26" stroke="#111" stroke-width="2"/><line x1="6" y1="31" x2="28" y2="31" stroke="#111" stroke-width="1.5"/><path d="M8 33h18l2 13H6z" fill="#fff"/><rect x="2" y="10" width="4" height="10" rx="2" fill="#111"/><rect x="28" y="10" width="4" height="10" rx="2" fill="#111"/><text x="17" y="41" text-anchor="middle" font-size="6.2" font-weight="900" fill="#f15a24">oOh!</text><path d="M6 45l5 5h4l-5-5zm8 0l5 5h4l-5-5zm8 0l5 5h2v-3l-2-2z" fill="#ffd400"/><path d="M9 45l5 5h-3l-5-5zm8 0l5 5h-3l-5-5zm8 0l4 4v-4z" fill="#e53935"/></svg></div>`;userMarker=L.marker([c.latitude,c.longitude],{icon:L.divIcon({className:'',html:uteSvg,iconSize:[34,54],iconAnchor:[17,45]}),zIndexOffset:1000}).addTo(map).bindPopup('You are here');if(!driving)render();updateDrivingView();}
let wakeLock=null;
let dashboardHideTimer=null;
let dashboardTouchStartY=null;
function showDrivingDashboard(autoHideMs=4000){
 const app=document.getElementById('app');
 if(!driving)return;
 app.classList.remove('dashboard-hidden');
 clearTimeout(dashboardHideTimer);
 const delay=autoHideMs===4000?driveSettings.autoHide:autoHideMs;if(delay>0)dashboardHideTimer=setTimeout(()=>hideDrivingDashboard(),delay);
}
function hideDrivingDashboard(){
 if(!driving)return;
 document.getElementById('app').classList.add('dashboard-hidden');
 clearTimeout(dashboardHideTimer);
}
function refreshDashboardAutoHide(ms=4000){showDrivingDashboard(ms);}

async function requestOrientation(){try{if(window.DeviceOrientationEvent&&typeof DeviceOrientationEvent.requestPermission==='function'){const ok=await DeviceOrientationEvent.requestPermission();if(ok!=='granted')return;}window.addEventListener('deviceorientation',e=>{const h=Number.isFinite(e.webkitCompassHeading)?e.webkitCompassHeading:(Number.isFinite(e.alpha)?360-e.alpha:null);if(Number.isFinite(h)&&(!lastSpeed||lastSpeed<8)){lastHeading=h;updateDrivingView();}},true);}catch(e){}}
async function requestScreenWakeLock(){
 try{
  if('wakeLock' in navigator){
   if(wakeLock){try{await wakeLock.release();}catch(e){} wakeLock=null;}
   wakeLock=await navigator.wakeLock.request('screen');
   wakeLock.addEventListener('release',()=>{wakeLock=null;});
  }
 }catch(e){console.warn('Screen wake lock unavailable',e);}
}
async function releaseScreenWakeLock(){if(wakeLock){try{await wakeLock.release();}catch(e){}wakeLock=null;}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&driving&&driveSettings.wake)requestScreenWakeLock();});
async function startDriving(){const planned=nearestDriveSite();if(planned){selectedId=planned.id;currentDriveSite=planned;selectSite(planned.id,true);}else{alert('No unfinished shelters are available. Import Today’s Jobs or add a route first.');return;}driving=true;followDriving=true;headingUp=true;last500Site=null;lastAlertSite=null;lastArrivalSite=null;document.getElementById('app').classList.add('driving','fullmap');document.getElementById('app').classList.remove('dashboard-hidden');document.getElementById('startDriving').textContent='🚗 Driving Active';if(driveSettings.wake)await requestScreenWakeLock();headingUp=driveSettings.orientation==='heading';const hour=new Date().getHours();if(hour<6||hour>=18){document.body.classList.add('night');document.getElementById('nightToggle').textContent='☀️ Day';}document.getElementById('followToggle').textContent='📍 Follow: On';document.getElementById('headingToggle').textContent='🧭 Heading-up: '+(headingUp?'On':'Off');labelMode='always';updateSiteLabelDisplay();map.invalidateSize();await requestOrientation();showDrivingDashboard(4000);if(navigator.geolocation){watchId=navigator.geolocation.watchPosition(handlePosition,()=>alert('Location unavailable. Allow Precise Location for Safari.'),{enableHighAccuracy:true,maximumAge:1000,timeout:15000});}else alert('GPS is not supported on this device.');}
async function stopDriving(){driving=false;await releaseScreenWakeLock();document.getElementById('startDriving').textContent='🚗 Start Driving';clearTimeout(dashboardHideTimer);document.getElementById('app').classList.remove('driving','fullmap','dashboard-hidden');if(routeLine){map.removeLayer(routeLine);routeLine=null;}if(watchId!==null){navigator.geolocation.clearWatch(watchId);watchId=null;}if(typeof map.setBearing==='function')map.setBearing(0);map.invalidateSize();render();}
document.getElementById('startDriving').onclick=startDriving;document.getElementById('stopDriving').onclick=stopDriving;
document.getElementById('followToggle').onclick=()=>{followDriving=!followDriving;document.getElementById('followToggle').textContent='📍 Follow: '+(followDriving?'On':'Off');if(followDriving)updateDrivingView();};
document.getElementById('headingToggle').onclick=()=>{headingUp=!headingUp;document.getElementById('headingToggle').textContent='🧭 Heading-up: '+(headingUp?'On':'Off');if(!headingUp&&typeof map.setBearing==='function')map.setBearing(0);else updateDrivingView();};
document.getElementById('nightToggle').onclick=()=>{document.body.classList.toggle('night');document.getElementById('nightToggle').textContent=document.body.classList.contains('night')?'☀️ Day':'🌙 Night';};
document.getElementById('fullScreen').onclick=()=>{document.getElementById('app').classList.toggle('fullmap');map.invalidateSize();if(document.documentElement.requestFullscreen)document.documentElement.requestFullscreen().catch(()=>{});};
document.getElementById('driveNavigate').onclick=()=>{if(currentDriveSite)appleMaps(currentDriveSite);};
document.getElementById('driveDone').onclick=()=>{if(currentDriveSite){showDrivingDashboard(5000);saveStatus(currentDriveSite.id,'cleaned');last500Site=null;lastAlertSite=null;lastArrivalSite=null;arrivalConfirmCount=0;speak('Site '+currentDriveSite.id+' completed. Selecting next shelter');updateDrivingView();}};
document.getElementById('driveSkip').onclick=()=>{if(currentDriveSite){showDrivingDashboard(5000);saveStatus(currentDriveSite.id,'skipped');last500Site=null;lastAlertSite=null;lastArrivalSite=null;arrivalConfirmCount=0;updateDrivingView();}};

const driveMiniBar=document.getElementById('driveMiniBar');
driveMiniBar.addEventListener('click',()=>showDrivingDashboard(5000));
driveMiniBar.addEventListener('touchstart',e=>{dashboardTouchStartY=e.touches[0].clientY;},{passive:true});
driveMiniBar.addEventListener('touchend',e=>{if(dashboardTouchStartY!==null&&dashboardTouchStartY-e.changedTouches[0].clientY>24)showDrivingDashboard(5000);dashboardTouchStartY=null;},{passive:true});
const driveDashboardEl=document.getElementById('driveDashboard');
driveDashboardEl.addEventListener('touchstart',e=>{dashboardTouchStartY=e.touches[0].clientY;},{passive:true});
driveDashboardEl.addEventListener('touchend',e=>{if(dashboardTouchStartY!==null&&e.changedTouches[0].clientY-dashboardTouchStartY>35)hideDrivingDashboard();dashboardTouchStartY=null;},{passive:true});
driveDashboardEl.addEventListener('click',e=>{if(!e.target.closest('button')){clearTimeout(dashboardHideTimer);dashboardHideTimer=setTimeout(()=>hideDrivingDashboard(),4000);}});


function populateSettings(){document.getElementById('setVoice').checked=!!driveSettings.voice;document.getElementById('setVibrate').checked=!!driveSettings.vibrate;document.getElementById('setWake').checked=!!driveSettings.wake;document.getElementById('setHide').value=String(driveSettings.autoHide);document.getElementById('setOrientation').value=driveSettings.orientation;document.getElementById('setArrival').value=String(driveSettings.arrivalMetres);}
function openSettings(){populateSettings();document.getElementById('settingsModal').classList.add('open');}
function closeSettings(){document.getElementById('settingsModal').classList.remove('open');}
document.getElementById('openSettings').onclick=openSettings;document.getElementById('closeSettings').onclick=closeSettings;document.getElementById('settingsModal').addEventListener('click',e=>{if(e.target.id==='settingsModal')closeSettings();});
document.getElementById('saveSettings').onclick=async()=>{driveSettings={voice:document.getElementById('setVoice').checked,vibrate:document.getElementById('setVibrate').checked,wake:document.getElementById('setWake').checked,autoHide:Number(document.getElementById('setHide').value),orientation:document.getElementById('setOrientation').value,arrivalMetres:Number(document.getElementById('setArrival').value)};localStorage.setItem('shelter_pro_drive_settings',JSON.stringify(driveSettings));headingUp=driveSettings.orientation==='heading';document.getElementById('headingToggle').textContent='🧭 Heading-up: '+(headingUp?'On':'Off');if(driving){if(driveSettings.wake)await requestScreenWakeLock();else await releaseScreenWakeLock();if(!headingUp&&typeof map.setBearing==='function')map.setBearing(0);showDrivingDashboard(driveSettings.autoHide);}closeSettings();};

function updateSiteLabelDisplay(){
 const el=document.getElementById('map');
 el.classList.remove('labels-auto','labels-always','labels-off','labels-zoomed');
 el.classList.add('labels-'+labelMode);
 if(map.getZoom()>=15)el.classList.add('labels-zoomed');
 const label=labelMode==='auto'?'Auto':labelMode==='always'?'Always':'Off';
 document.getElementById('siteLabels').textContent='Site numbers: '+label;
}
document.getElementById('siteLabels').onclick=()=>{
 labelMode=labelMode==='auto'?'always':labelMode==='always'?'off':'auto';
 localStorage.setItem('ooh_site_labels',labelMode);
 updateSiteLabelDisplay();
};
map.on('zoomend',updateSiteLabelDisplay);
updateSiteLabelDisplay();
render();if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('service-worker.js'));
